#include <zephyr/ztest.h>
#include <zephyr/drivers/modem/modem_ubx.h>
#include <zephyr/drivers/modem/modem_context.h>
#include <zephyr/drivers/modem/modem_iface.h>
#include "test_script_runner.h"

#include <string.h>
#include <stdio.h>

/* Define a modem context and interface for the test */
static struct modem_iface_uart_data uart_data;
static struct modem_iface_data iface_data = {
    .uart = &uart_data,
};
static struct modem_context modem_ctx;
static struct modem_ubx_data ubx_data;

/* Semaphore to signal response reception */
static K_SEM_DEFINE(rsp_sem, 0, 1);

/* Response handler for modem_ubx_send */
static void ubx_response_handler(struct modem_ubx_data *data,
                                 enum ubx_msg_type type,
                                 uint8_t msg_class, uint8_t msg_id,
                                 uint16_t len, uint8_t *payload)
{
    printk("UBX response received: class=0x%02x, id=0x%02x, len=%d\n",
           msg_class, msg_id, len);

    /* Check if it's an ACK for the command we sent */
    if (type == UBX_MSG_ACK && msg_class == UBX_CLASS_ACK && msg_id == UBX_ID_ACK) {
        if (len == 2 && payload[0] == UBX_CLASS_CFG && payload[1] == UBX_ID_CFG_PRT) {
            printk("Received ACK for CFG-PRT\n");
            k_sem_give(&rsp_sem);
        }
    } else if (type == UBX_MSG_ACK && msg_class == UBX_CLASS_ACK && msg_id == UBX_ID_NAK) {
        printk("Received NAK for CFG-PRT\n");
        k_sem_give(&rsp_sem); /* Still a response, just a negative one */
    }
}

/* Test script runner instance */
static struct test_script_runner test_script_runner;

/* Setup function for tests */
static void test_modem_ubx_setup(void)
{
    /* Initialize modem context and UBX data */
    modem_context_init(&modem_ctx, &iface_data);
    modem_ubx_init(&ubx_data, &modem_ctx);

    /* Initialize test script runner */
    test_script_runner_init(&test_script_runner, &iface_data);
}

/* Teardown function for tests */
static void test_modem_ubx_teardown(void)
{
    test_script_runner_deinit(&test_script_runner);
    modem_ubx_deinit(&ubx_data);
    modem_context_deinit(&modem_ctx);
}

/* Test case: Command with response blocks and receives response */
ZTEST(modem_ubx, test_cmd_rsp_blocks_and_receives_rsp)
{
    /* UBX-CFG-PRT command (example: default UART1 config) */
    /* Class: 0x06 (CFG), ID: 0x00 (PRT) */
    /* Length: 20 bytes */
    /* Payload: 01 00 00 00 D0 08 00 00 00 00 00 00 07 00 03 00 00 00 00 00 */
    /* Checksum: 0xFD 0x18 (recalculated) */
    static const uint8_t ubx_cfg_prt_cmd[] = {
        0xB5, 0x62, 0x06, 0x00, 0x14, 0x00, /* Header, Class, ID, Length */
        0x01, 0x00, 0x00, 0x00, 0xD0, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, /* Payload */
        0x07, 0x00, 0x03, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, /* Payload */
        0xFD, 0x18 /* Checksum (CK_A, CK_B) */
    };

    /* Expected UBX-ACK-ACK for UBX-CFG-PRT (Class 0x06, ID 0x00) */
    /* Class: 0x05 (ACK), ID: 0x01 (ACK) */
    /* Length: 2 bytes */
    /* Payload: 06 00 (ACKed Class, ACKed ID) */
    /* Checksum: 0x0E 0x37 (recalculated) */
    static const uint8_t ubx_ack_ack_rsp[] = {
        0xB5, 0x62, 0x05, 0x01, 0x02, 0x00, /* Header, Class, ID, Length */
        0x06, 0x00, /* Payload */
        0x0E, 0x37 /* Checksum (CK_A, CK_B) */
    };

    /* Define the test script */
    static const struct test_script_entry script[] = {
        TEST_SCRIPT_ENTRY_TX(ubx_cfg_prt_cmd, sizeof(ubx_cfg_prt_cmd)),
        TEST_SCRIPT_ENTRY_RX(ubx_ack_ack_rsp, sizeof(ubx_ack_ack_rsp)),
    };

    /* Reset semaphore before test */
    k_sem_reset(&rsp_sem);

    /* Start the script runner */
    test_script_runner_start(&test_script_runner, script, ARRAY_SIZE(script), K_SECONDS(5));

    /* Send the UBX command and expect a response */
    int ret = modem_ubx_send(&ubx_data, UBX_CLASS_CFG, UBX_ID_CFG_PRT,
                             &ubx_cfg_prt_cmd[6], 20, /* Payload starts after 6 bytes, length is 20 */
                             ubx_response_handler, K_SECONDS(2));

    zassert_equal(ret, 0, "modem_ubx_send failed with error %d", ret);

    /* Wait for the response semaphore to be given by the handler */
    ret = k_sem_take(&rsp_sem, K_SECONDS(2));
    zassert_equal(ret, 0, "Did not receive UBX ACK within timeout");

    /* Stop the script runner and check if it completed successfully */
    test_script_runner_stop(&test_script_runner);
    zassert_true(test_script_runner.result.done, "Test script runner did not complete");
    zassert_equal(test_script_runner.result.error, 0, "Test script runner error: %d", test_script_runner.result.error);
}

/* Test case: Command with no response is non-blocking */
ZTEST(modem_ubx, test_cmd_no_rsp_is_non_blocking)
{
    /* Example: UBX-NAV-POSECEF (Class 0x01, ID 0x01), no payload, no expected ACK */
    /* B5 62 01 01 00 00 02 09 */
    /* Checksum: 0x02 0x09 (recalculated) */
    static const uint8_t dummy_cmd[] = {
        0xB5, 0x62, 0x01, 0x01, 0x00, 0x00, /* Header, Class, ID, Length */
        0x02, 0x09 /* Checksum (CK_A, CK_B) */
    };

    static const struct test_script_entry script[] = {
        TEST_SCRIPT_ENTRY_TX(dummy_cmd, sizeof(dummy_cmd)),
    };

    k_sem_reset(&rsp_sem); /* Ensure semaphore is reset */

    test_script_runner_start(&test_script_runner, script, ARRAY_SIZE(script), K_MSEC(500));

    /* Send a command that doesn't expect a response (or we don't care about it for this test) */
    int ret = modem_ubx_send(&ubx_data, 0x01, 0x01, NULL, 0, NULL, K_MSEC(100));

    zassert_equal(ret, 0, "modem_ubx_send failed with error %d", ret);

    /* The key for "non-blocking" is that the test doesn't wait for a response. */
    /* The script runner should still complete if the TX data is matched. */
    test_script_runner_stop(&test_script_runner);
    zassert_true(test_script_runner.result.done, "Test script runner did not complete for non-blocking cmd");
    zassert_equal(test_script_runner.result.error, 0, "Test script runner error: %d", test_script_runner.result.error);
}

ZTEST_SUITE(modem_ubx, NULL, NULL, test_modem_ubx_setup, test_modem_ubx_teardown, NULL);
